column32:
triggerer.IfStat( is_hidden_monster, 0,
{
	IfStat( is_totem_object, 0,
	{
		If( this.dont_dupe != 1,
		{
			this.dont_dupe = 1;
			this.clone = CreateClone( this, copy_mods:true, disable_drops:false );
			this.clone.dont_dupe = 1;
			this.clone.SetLocation( FindRandomLocationNearLocation( 5, 25, this.GetLocation() ) );
			this.clone.AddStat( dropped_items_are_duplicated, 1 );
			this.clone.AddMonsterExplicitMod( MonsterTagMirrored );
			this.clone.PlayEffect( LakeKalandraDuplicateSpawnIn );
		} );
	} );
} );

triggerer.If( Or( GetState( vol_dead ) == 0, GetState( det_dead ) == 0 ), ()
{
	triggerer.boss_shaman = this;
	triggerer.SetStateTo( det_dead, 1 );
} );

triggerer.If( Or( GetState( vol_dead ) == 0, GetState( det_dead ) == 0 ), ()
{
	triggerer.boss_shaman = this;
	triggerer.SetStateTo( vol_dead, 1 );
} );

triggerer.If( Or( GetState( vol_dead ) == 0, GetState( det_dead ) == 0 ), ()
{
	triggerer.boss_shaman = this;
	triggerer.SetStateTo( vol_dead, 1 );
} );

column35:
/* the 50 in here is the Length of the GA skill using this ExecuteGEAL */
triggerer.vac_suck_dir = Mod( EvalIf( Eval( CalculateOrientation( this ) - GetOrientation() ) < 0.0, Eval( CalculateOrientation( this ) - GetOrientation() ) + 360, CalculateOrientation( this ) - GetOrientation() ), 360 );
If( Or( vac_suck_dir <= 45.0, vac_suck_dir > 315.0 ), { InterruptActionsForDuration( 0.3, TakeHitBackward ); } );
If( And( vac_suck_dir > 45.0, vac_suck_dir <= 135.0 ), { InterruptActionsForDuration( 0.3, TakeHitRight ); } );
If( And( vac_suck_dir > 135.0, vac_suck_dir <= 225.0 ), { InterruptActionsForDuration( 0.3, TakeHitForward ); } );
If( And( vac_suck_dir > 225.0, vac_suck_dir <= 315.0 ), { InterruptActionsForDuration( 0.3, TakeHitLeft ); } );
triggerer.MoveToOverTime( this.vacuum, GetDistanceTo( this.vacuum ) / Eval( 50 / 0.3 ), false, false, true, true ); 
triggerer.If( GetCurrentMoveSpeed() > 0.0, (){ Accelerate( time:0.3 * 2.0 ); } );

column32:
triggerer.PlayEffect( "Metadata/Effects/Spells/monsters_effects/Act1_FOUR/Skeleton_Golemancer/skelenado_spawn.ao" );
triggerer.SetCorpseUsable( false );
triggerer.Do( ( the_corpse )
{
	Delay( 0.2, 
	{
		this.TriggerSkill( SkelemancerSkelenado, the_corpse, origin_override:the_corpse );
		the_corpse.Delete();
	} );
} );

triggerer.IfTypeContains( NormalMedallion, (){ triggerer.SetStateTo( activated, 1 ); }, ()
		{
			Revive();
			DoAction( Revive );
			AddBuff( monster_no_drops_buff, infinity, 1 );
			SetStateTo( ghostflame, 1 );
			SetCorpseUsable( true );
		} );

triggerer.IfTypeContains( Mushroom, ()
{
	If( GetStateTimer( explode ) <= 0.0, ()
	{
		StartStateTimer( explode, GetDistanceTo( this ) * 0.01 );
	} );
} );

triggerer.If( HasNamedTask( VoodooKingDeathEffigyDebuffRemoval ), (){ triggerer.RemoveNamedTask( VoodooKingDeathEffigyDebuffRemoval ); } );
triggerer.AddBuffWithOwner( voodoo_king_death_effigy_multiplying_curse, 4.5, this );
triggerer.If( VariableExists( voodoo_death_curse ), (){ triggerer.voodoo_death_curse = triggerer.voodoo_death_curse + 1; }, (){ triggerer.voodoo_death_curse = 1; } );
triggerer.AddBuff( voodoo_king_death_effigy_multiplying_curse_damage, 0.2, CalculateDamage( Clamp( Pow( 2, triggerer.voodoo_death_curse ), 150, 1500000 ), 0.01 ) );
triggerer.AddNamedDelay( VoodooKingDeathEffigyDebuffRemoval, 5.0, { triggerer.voodoo_death_curse = null; } );

triggerer.IfTypeContains( NormalMedallion, (){ triggerer.SetStateTo( activated, 1 ); }, ()
		{
			Revive();
			DoAction( Revive );
			AddBuff( monster_no_drops_buff, infinity, 1 );
			SetStateTo( ghostflame, 1 );
			SetCorpseUsable( true );
		} );

